import React, { useState } from "react";
import "./AddCardSubtask.css";
import axios from "axios";

const AddCardSubtask = ({prop}) => {
    const [newName,setNewName] = useState();
    const handleName = (e) => {
        setNewName(e.target.value);
    }

    const putSubtask = async () => {
        await axios.post('http://localhost:3001/api/subtask',{name: newName, state: false, id_task: prop.prop.id}).then(result => {
            prop.subtasks.push({id: result.data.id,name: newName, state: false, id_task: prop.prop.id})
        })
    }

    const handleAddSub = () => {
        if (newName) {
            //запрос на сервер 
            //после запрос обновление списка subtask   
            putSubtask();
            prop.setTarg(false);
            
        }
    }

    return(
        <div className="cardSub">
            <input className="insertName" onChange={handleName}></input>
            <button className="buttonAddSub" onClick={handleAddSub}>ОК</button>
        </div>
    )

}

export default AddCardSubtask;
